MOD = 10**9+7


def main(input, print):
    n, k = map(int, input().split())
    a = list(map(int, input().split()))
    nc = 0
    for i in range(n):
        if a[i] < 0:
            nc += 1
    negative = 0
    cnt = 0
    ans = 1
    a = sorted(a, key=abs, reverse=True)
    y = 0
    for i in range(n):
        if k == cnt:
            break
        if a[i] < 0:
            if k-cnt > 1:
                if negative % 2 == 1:
                    ans = ans * y * a[i] % MOD
                    cnt += 2
                else:
                    y = a[i]
                negative += 1
        else:
            ans = ans * a[i] % MOD
            cnt += 1
    if cnt == k:
        print(ans)
        return
    ans = 1
    a = sorted(a, key=abs)
    y = 0
    for i in range(k):
        ans = ans * a[i] % MOD

    print(ans)


