def count_triplets(string):
    count = 0
    for i in range(len(string) - 2):
        for j in range(i + 1, len(string) - 1):
            for k in range(j + 1, len(string)):
                if string[i] != string[j] and string[i] != string[k] and string[j] != string[k]:
                    count += 1
    return count

