def one_card_poker(a, b):
    strength = {2: 1, 3: 2, 4: 3, 5: 4, 6: 5, 7: 6, 8: 7, 9: 8, 10: 9, 11: 10, 12: 11, 13: 12}
    if strength[a] > strength[b]:
        return "Alice"
    elif strength[a] < strength[b]:
        return "Bob"
    else:
        return "Draw"


