for i in range(1, n+1):
    if connected[i] is None:
        connected[i] = path_id

    if i not in paths.keys():
        pass
    else:
        stack = deque(paths[i])
        cluster = set([i]+paths[i])
        while len(stack) > 0:
            j = stack.pop()
            connected[j] = path_id
            for k in paths[j]:
                if connected[k] is None and not k in cluster:
                    stack.append(k)
                    cluster.add(k)
    path_id += 1
