        for j in range(W):
            if a[i][j] > 0:
                for di in range(-1, 2):
                    for dj in range(-1, 2):
                        if abs(di) + abs(dj) == 1:
                            move_coin(a, i, j, di, dj)
                            count += 1
                            if count_even(a) == H * W:
                                return count
                            move_coin(a, i, j, -di, -dj)
    return -1

