def get_max_length(s):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(i, n):
            if s[i] == 'A' and s[j] == 'Z':
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j] + 1)
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])
    return dp[0][n - 1]

