def find_min_cost(costs, times, target_time):
    min_cost = float('inf')
    for i in range(len(costs)):
        if times[i] <= target_time:
            min_cost = min(min_cost, costs[i])
    if min_cost == float('inf'):
        return 'TLE'
    return min_cost

