def listCount_dash(S,K):
    box =""
    S_origin = copy.deepcopy(S)

    #Sの後ろから前まで試行
    for k in range(0,len(S)-1):
        #もし先頭と最後尾が同じならque
        if S[0] == S[len(S)-1]:
            S.append(S[0])
            S.pop(0)
        else:
            break

    return listCount(S,K)*(K-1) + listCount(S_origin,K)

