from math import gcd

def count_coprime_divisors(a, b):
    g = gcd(a, b)
    count = 0
    for i in range(1, int(g**0.5) + 1):
        if g % i == 0:
            if gcd(i, g // i) == 1:
                count += 2
            elif i == g // i:
                count += 1
    return count

