def solve(H, spells):
    dp = [float('inf')] * (H + 1)
    dp[0] = 0
    for i in range(1, H + 1):
        for a, b in spells:
            if i - a >= 0:
                dp[i] = min(dp[i], dp[i - a] + b)
    return dp[H]

