def solve(n):
    mod = 10**9 + 7
    dp = [[0 for _ in range(10)] for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(10):
            for k in range(10):
                dp[i][j] = (dp[i][j] + dp[i - 1][k]) % mod
    ans = 0
    for i in range(1, 10):
        ans = (ans + dp[n][i]) % mod
    return ans

n = int(input())
print(solve(n))

