def count_strings(A):
    n = len(A)
    count = 1  # Count the original string
    for i in range(n):
        for j in range(i + 1, n):
            if A[i:j] != A[j - 1:i - 1:-1]:  # Check if the reversed substring is different
                count += 1
    return count

