def is_isomorphic(s, t):
  if len(s) != len(t):
    return False
  mapping = {}
  for i in range(len(s)):
    if s[i] in mapping:
      if mapping[s[i]] != t[i]:
        return False
    else:
      if t[i] in mapping.values():
        return False
      mapping[s[i]] = t[i]
  return True

def is_normal_form(s):
  for i in range(len(s)):
    for j in range(i + 1, len(s)):
      if s[i] == s[j] and s[i] < s[j]:
        return False
  return True

def generate_normal_strings(n):
  result = []
  def backtrack(current, used):
    if len(current) == n:
      if is_normal_form(current):
        result.append(current)
      return
    for i in range(26):
      char = chr(ord('a') + i)
      if char not in used:
        used.add(char)
        backtrack(current + char, used)
        used.remove(char)
  backtrack("", set())
  return result

