    # Initialize a list to store the indices of the problems
    problems = []

    # Iterate from 1 to n
    for i in range(1, n + 1):
        # If the current problem has a score of i, add it to the list
        if i % n == 0:
            problems.append(i)

    # Return the list of problems
    return problems

