def count_arrangements(n, k):
    # Initialize the dp array with 1s
    dp = [1] * (k + 1)

    # Loop through the remaining balls
    for i in range(1, n):
        # Update the dp array based on the previous arrangement
        for j in range(k, 0, -1):
            dp[j] = (dp[j] + dp[j - 1]) % 1000000007

    return dp[k]


