def f(n, x):
    if n == 0:
        return 1
    if x == 1:
        return 0
    elif 1 < x <= a[n-1] + 1:
        return f(n-1, x-1)
    elif x == a[n-1] + 2:
        return p[n-1] + 1
    elif a[n-1] + 2 < x < 2 * a[n-1] + 2:
        return p[n-1] + 1 + f(n-1, x-a[n-1]-2)
    else:
        return 2 * p[n-1] + 1

