def get_min_repaint_tiles(S):
    n = len(S)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        if S[i - 1] == "0":
            dp[i] = min(dp[i], dp[i - 1] + 1)
        else:
            dp[i] = min(dp[i], dp[i - 1] + (1 if i < n and S[i] == "0" else 0))
    return dp[n]

