ans = [(M_index, i) for i in range(1, N + 1)]
# 隣り合う数を見ていく
if M >= 0:
    for i in range(N - 1):
        if A[i] > A[i + 1]:
            ans.append((i + 1, i + 2))
else:
    for i in range(N - 1, 0, -1):
        if A[i - 1] > A[i]:
            ans.append((i + 1, i))

print(len(ans))
for x, y in ans:
    print(x, y)

