N = int(input())
S = input()
max_val = 0


for j in range(len(S)):
    s = S[j:]
    z = [0]*len(s)
    n = len(s)
    L = 0
    R = 0
    for i in range(1, n):
        if i > R:
            L = i
            R = i
            while (R < n) and (s[R - L] == s[R]):
                z[i] = R - L + 1
                if z[i] > i:
                    z[i] = i
                    break
                R += 1
        else:
            k = i - L
            if z[k] < R - i + 1:
                if z[k] <= i:
                    z[i] = z[k]
                else:
                    z[i] = i
            else:
                L = i
                while (R < n) and (s[R - L] == s[R]):
                    z[i] = R - L + 1
                    if z[i] > i:
                        z[i] = i
                        break
                    R += 1
    max_z = max(z)
    if max_z > max_val:
        max_val = max(z)

print(max_val)

