S = input()
mod = 10 ** 9 + 7

def DP(i, j, S):
    if i == len(S):
        return 1 if j == 3 else 0

    if S[i] == "?":
        base = 3 * DP(i+1, j, S)
        if j < 3:
            base += DP(i+1, j+1, S)
    elif j < 3 and S[i] == "ABC"[j]:
        base = DP(i+1, j, S) + DP(i+1, j+1, S)
    else:
        base = DP(i+1, j, S)

    return base % mod

print(DP(0, 0, S))
